class Solution {

    public int maxSubArray(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        var max = Integer.MIN_VALUE;
        var prefixMin = 0;
        var sum = 0;
        for (var i = 0; i < nums.length; i++) {
            sum += nums[i];
            max = Math.max(max, sum - prefixMin);
            prefixMin = Math.min(prefixMin, sum);
        }

        return max;
    }

}

